def angles(ca,lo,hi,local=True):
    idx=[i for i in range(lo,hi+1) if i in ca]
    P=np.array([ca[i] for i in idx]); A=np.linalg.svd(P-P.mean(0),full_matrices=False)[2][0]
    if np.dot(P[-1]-P[0],A)<0: A=-A
    u=np.cross(A,[0,0,1.0]); u=np.cross(A,[0,1.0,0]) if np.linalg.norm(u)<1e-6 else u
    u/=np.linalg.norm(u); v=np.cross(A,u); out={}
    for k,i in enumerate(idx):
        if local:
            w=[ca[j] for j in range(i-3,i+4) if j in ca]
            if len(w)<5: continue
            c=np.mean(w,0)
        else:
            c=P.mean(0)+np.dot(P[k]-P.mean(0),A)*A      # global axis -> supercoil retained
        r=P[k]-c; r=r-np.dot(r,A)*A
        out[i]=np.degrees(np.arctan2(np.dot(r,v),np.dot(r,u)))%360
    return out
G=np.arange(88,112,0.06)
def fit(ang):
    i=np.array(sorted(ang)); a=np.radians(np.array([ang[k] for k in i]))
    E=np.exp(1j*(a[None,:]-np.radians(G)[:,None]*i[None,:])).mean(1)
    R=np.abs(E); b=int(R.argmax()); return G[b],R[b],R
def boot(ang,n=120):
    i=np.array(sorted(ang)); v=[]
    for _ in range(n):
        s=rng.choice(len(i),len(i),replace=True); sub={i[k]:ang[i[k]] for k in s}
        if len(sub)>=10: v.append(fit(sub)[0])
    return np.percentile(v,[2.5,97.5])
